static int largest(int *heights, int n) {
  int *stack = (int *)malloc(sizeof(int) * (n + 1));
  int top = -1, maxArea = 0;
  for (int i = 0; i <= n; i++) {
    int h = (i == n) ? 0 : heights[i];
    while (top >= 0 && heights[stack[top]] > h) {
      int height = heights[stack[top--]];
      int width = top < 0 ? i : i - stack[top] - 1;
      if (height * width > maxArea) maxArea = height * width;
    }
    stack[++top] = i;
  }
  free(stack);
  return maxArea;
}

int maximalRectangle(char **matrix, int matrixSize, int *matrixColSize) {
  if (matrixSize == 0) return 0;
  int n = matrixColSize[0];
  int *heights = (int *)calloc(n, sizeof(int));
  int maxArea = 0;
  for (int i = 0; i < matrixSize; i++) {
    for (int j = 0; j < n; j++) {
      heights[j] = matrix[i][j] == '1' ? heights[j] + 1 : 0;
    }
    int a = largest(heights, n);
    if (a > maxArea) maxArea = a;
  }
  free(heights);
  return maxArea;
}

class Solution {
  int largest(vector<int> &heights) {
    int n = heights.size(), maxArea = 0;
    stack<int> st;
    for (int i = 0; i <= n; i++) {
      int h = (i == n) ? 0 : heights[i];
      while (!st.empty() && heights[st.top()] > h) {
        int height = heights[st.top()];
        st.pop();
        int width = st.empty() ? i : i - st.top() - 1;
        maxArea = max(maxArea, height * width);
      }
      st.push(i);
    }
    return maxArea;
  }

public:
  int maximalRectangle(vector<vector<char>> &matrix) {
    if (matrix.empty()) return 0;
    int n = matrix[0].size(), maxArea = 0;
    vector<int> heights(n, 0);
    for (int i = 0; i < (int)matrix.size(); i++) {
      for (int j = 0; j < n; j++) {
        heights[j] = matrix[i][j] == '1' ? heights[j] + 1 : 0;
      }
      maxArea = max(maxArea, largest(heights));
    }
    return maxArea;
  }
};

func largest(heights []int) int {
	stack := []int{}
	maxArea := 0
	n := len(heights)
	for i := 0; i <= n; i++ {
		h := 0
		if i < n {
			h = heights[i]
		}
		for len(stack) > 0 && heights[stack[len(stack)-1]] > h {
			height := heights[stack[len(stack)-1]]
			stack = stack[:len(stack)-1]
			width := i
			if len(stack) > 0 {
				width = i - stack[len(stack)-1] - 1
			}
			if height*width > maxArea {
				maxArea = height * width
			}
		}
		stack = append(stack, i)
	}
	return maxArea
}

func maximalRectangle(matrix [][]byte) int {
	if len(matrix) == 0 {
		return 0
	}
	n := len(matrix[0])
	heights := make([]int, n)
	maxArea := 0
	for i := 0; i < len(matrix); i++ {
		for j := 0; j < n; j++ {
			if matrix[i][j] == '1' {
				heights[j]++
			} else {
				heights[j] = 0
			}
		}
		if a := largest(heights); a > maxArea {
			maxArea = a
		}
	}
	return maxArea
}

class Solution {
  private int largest(int[] heights) {
    int n = heights.length, maxArea = 0;
    Deque<Integer> st = new ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
      int h = (i == n) ? 0 : heights[i];
      while (!st.isEmpty() && heights[st.peek()] > h) {
        int height = heights[st.pop()];
        int width = st.isEmpty() ? i : i - st.peek() - 1;
        maxArea = Math.max(maxArea, height * width);
      }
      st.push(i);
    }
    return maxArea;
  }

  public int maximalRectangle(char[][] matrix) {
    if (matrix.length == 0) return 0;
    int n = matrix[0].length, maxArea = 0;
    int[] heights = new int[n];
    for (int i = 0; i < matrix.length; i++) {
      for (int j = 0; j < n; j++) {
        heights[j] = matrix[i][j] == '1' ? heights[j] + 1 : 0;
      }
      maxArea = Math.max(maxArea, largest(heights));
    }
    return maxArea;
  }
}

class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix:
            return 0
        n = len(matrix[0])
        heights = [0] * n
        max_area = 0

        def largest(hs: List[int]) -> int:
            st = []
            best = 0
            for i in range(len(hs) + 1):
                h = hs[i] if i < len(hs) else 0
                while st and hs[st[-1]] > h:
                    height = hs[st.pop()]
                    width = i if not st else i - st[-1] - 1
                    best = max(best, height * width)
                st.append(i)
            return best

        for row in matrix:
            for j in range(n):
                heights[j] = heights[j] + 1 if row[j] == "1" else 0
            max_area = max(max_area, largest(heights))
        return max_area

impl Solution {
  fn largest(heights: &[i32]) -> i32 {
    let n = heights.len();
    let mut st: Vec<usize> = vec![];
    let mut max_area = 0;
    for i in 0..=n {
      let h = if i < n { heights[i] } else { 0 };
      while let Some(&top) = st.last() {
        if heights[top] <= h {
          break;
        }
        let height = heights[st.pop().unwrap()];
        let width = if st.is_empty() {
          i as i32
        } else {
          i as i32 - *st.last().unwrap() as i32 - 1
        };
        max_area = max_area.max(height * width);
      }
      st.push(i);
    }
    max_area
  }

  pub fn maximal_rectangle(matrix: Vec<Vec<char>>) -> i32 {
    if matrix.is_empty() {
      return 0;
    }
    let n = matrix[0].len();
    let mut heights = vec![0i32; n];
    let mut max_area = 0;
    for row in &matrix {
      for j in 0..n {
        heights[j] = if row[j] == '1' { heights[j] + 1 } else { 0 };
      }
      max_area = max_area.max(Solution::largest(&heights));
    }
    max_area
  }
}

const maximalRectangle = (matrix: string[][]): number => {
  if (matrix.length === 0) return 0;
  const n = matrix[0].length;
  const heights: number[] = new Array(n).fill(0);
  let maxArea = 0;

  const largest = (hs: number[]): number => {
    const st: number[] = [];
    let best = 0;
    for (let i = 0; i <= hs.length; i++) {
      const h = i < hs.length ? hs[i] : 0;
      while (st.length && hs[st[st.length - 1]] > h) {
        const height = hs[st.pop()!];
        const width = st.length === 0 ? i : i - st[st.length - 1] - 1;
        best = Math.max(best, height * width);
      }
      st.push(i);
    }
    return best;
  };

  for (const row of matrix) {
    for (let j = 0; j < n; j++) {
      heights[j] = row[j] === '1' ? heights[j] + 1 : 0;
    }
    maxArea = Math.max(maxArea, largest(heights));
  }
  return maxArea;
};
